// Smoke-tests the service worker generated by the webpack build: it must load,
// import a Workbox runtime that exists, and precache files that exist in the
// build, including index.html. Catches regressions from the Workbox version
// used by @vue/cli-plugin-pwa (see the override in package.json).
//
// Usage: node scripts/check-service-worker.mjs [distDir]
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';

const dist = path.resolve(process.argv[2] || 'dist');
const die = msg => {
  console.error(`check-service-worker: ${msg}`);
  process.exit(1);
};

const swPath = path.join(dist, 'service-worker.js');
if (!fs.existsSync(swPath)) die(`${swPath} not found`);

// The worker registers itself through an AMD-style define(); capture it
// instead of loading the real Workbox runtime.
let deps;
let factory;
const sandbox = { addEventListener: () => undefined, skipWaiting: () => undefined };
sandbox.self = sandbox;
sandbox.define = (d, f) => {
  deps = d;
  factory = f;
};
vm.runInNewContext(fs.readFileSync(swPath, 'utf8'), sandbox, { filename: swPath });
if (!deps || !factory) die('service worker did not call define()');

for (const dep of deps) {
  if (dep === 'require' || dep === 'exports') continue;
  if (!fs.existsSync(path.join(dist, `${dep}.js`))) die(`missing Workbox module ${dep}.js`);
}

// Record the Workbox calls the worker makes, accepting any API it uses.
const calls = [];
// Proxy targets must be functions so they can be called and constructed.
const noop = () => undefined;
const stub = new Proxy(noop, {
  get: (_target, name) =>
    new Proxy(
      function () {
        return undefined;
      },
      {
        apply: (_t, _this, args) => {
          calls.push([name, args]);
          return stub;
        },
        construct: () => stub,
      }
    ),
});
factory(stub);

const precache = calls.find(([name]) => name === 'precacheAndRoute');
if (!precache) die('service worker does not call precacheAndRoute()');
// URLs are relative to the web root, e.g. /index.html.
const urls = precache[1][0].map(entry => entry.url.replace(/^\//, ''));
if (!urls.includes('index.html')) die('index.html is not precached');
for (const url of urls) {
  if (!fs.existsSync(path.join(dist, url))) die(`precached file ${url} is missing from the build`);
}
console.log(`check-service-worker: OK, ${urls.length} precached files`);
